import { Bubble } from '@refy-design/web';
import { Button } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function BubbleExample() {
  const [sent, setSent] = useState(false);
  return (
    <div style={stack}>
      <Bubble>Can we review the material today?</Bubble>
      {sent && <Bubble side="end">Yes, the review is confirmed.</Bubble>}
      <Button onClick={() => setSent(!sent)}>{sent ? 'Clear answer' : 'Reply'}</Button>
    </div>
  );
}
export function Example() {
  return <BubbleExample />;
}
